const data = await fetch("/api/dashboard").then((response) => {
  if (!response.ok) throw new Error(`/api/dashboard: ${response.status}`);
  return response.json();
});
const yen = new Intl.NumberFormat("ja-JP");
const formatVolume=(value)=>typeof value==="number"?yen.format(value):(value??"未取得");
document.querySelector("#freshness").textContent = `DFS実測 · ${new Date(data.generated_at).toLocaleString("ja-JP")}`;

const siteSelector=document.querySelector("#site-selector");
const pinnedSites=data.sites.filter((site)=>site.is_pinned).sort((a,b)=>a.display_order-b.display_order).slice(0,4);
const requestedSite=new URLSearchParams(location.search).get("site");
siteSelector.value=data.sites.some((site)=>site.site_id===requestedSite)?requestedSite:(pinnedSites[0]?.site_id??data.sites[0].site_id);
pinnedSites.forEach((site)=>siteSelector.insertAdjacentHTML("beforeend",`<button type="button" role="tab" class="site-tab ${site.site_id===siteSelector.value?"active":""}" data-site="${site.site_id}">${site.label}</button>`));
siteSelector.insertAdjacentHTML("beforeend",'<button type="button" class="site-directory-trigger">サイト一覧</button>');
const metricLabels = {total_keywords:"対象KW",actionable_main_keywords:"施策メインKW",new_article_candidates:"新規記事候補",wp_articles_assigned:"記事ID割当"};
function renderMetrics(groups){const metrics={total_keywords:groups.reduce((sum,group)=>sum+1+group.intent_keywords.length,0),actionable_main_keywords:groups.length,new_article_candidates:groups.filter((group)=>group.state==="未施策").length,wp_articles_assigned:groups.filter((group)=>group.wp_article_id!=null).length};document.querySelector("#metrics").innerHTML=Object.entries(metrics).map(([key,value])=>`<div class="metric"><span>${metricLabels[key]}</span><strong>${yen.format(value)}</strong><small>件</small></div>`).join("")}

document.querySelectorAll(".tab").forEach((tab)=>tab.addEventListener("click",()=>{
  document.querySelectorAll(".tab,.view").forEach((node)=>node.classList.remove("active"));
  tab.classList.add("active"); document.querySelector(`#${tab.dataset.view}`).classList.add("active");
}));

const rowsRoot = document.querySelector("#keyword-rows");
const queryRowsRoot=document.querySelector("#query-rows");
const detail = document.querySelector("#group-detail");
const dialog = document.querySelector("#detail-dialog");
document.querySelector("#detail-close").addEventListener("click",()=>dialog.close());
dialog.addEventListener("click",(event)=>{if(event.target===dialog)dialog.close()});
const siteDialog=document.querySelector("#site-dialog");
const siteSearch=document.querySelector("#site-search");
const siteList=document.querySelector("#site-list");
document.querySelector("#site-close").addEventListener("click",()=>siteDialog.close());
siteSelector.querySelector(".site-directory-trigger").addEventListener("click",()=>siteDialog.showModal());
function activateSite(siteId){siteSelector.value=siteId;siteSelector.querySelectorAll(".site-tab").forEach((item)=>item.classList.toggle("active",item.dataset.site===siteId));selectSite();if(siteDialog.open)siteDialog.close()}
function renderSiteList(){const query=siteSearch.value.trim().toLocaleLowerCase("ja-JP");const sites=data.sites.filter((site)=>`${site.label} ${site.domain}`.toLocaleLowerCase("ja-JP").includes(query));siteList.innerHTML=sites.map((site)=>`<button type="button" class="site-list-item" data-site="${site.site_id}"><span><strong>${site.label}</strong><small>${site.domain}</small></span><em>${site.status}</em></button>`).join("");siteList.querySelectorAll(".site-list-item").forEach((item)=>item.addEventListener("click",()=>activateSite(item.dataset.site)))}
siteSearch.addEventListener("input",renderSiteList);renderSiteList();
const filters={search:document.querySelector("#keyword-search"),categoryParent:document.querySelector("#category-parent-filter"),categoryChild:document.querySelector("#category-child-filter"),categoryGrandchild:document.querySelector("#category-grandchild-filter"),parent:document.querySelector("#parent-filter"),state:document.querySelector("#state-filter")};
const pageSizeControl=document.querySelector("#page-size");
const pagination=document.querySelector("#pagination");
let currentPage=1;
let categoryDepth=1;
const queryFilters={search:document.querySelector("#query-search"),categoryParent:document.querySelector("#query-category-parent-filter"),categoryChild:document.querySelector("#query-category-child-filter"),categoryGrandchild:document.querySelector("#query-category-grandchild-filter"),article:document.querySelector("#query-article-filter"),period:document.querySelector("#query-period-filter")};
const queryPageSizeControl=document.querySelector("#query-page-size");
const queryPagination=document.querySelector("#query-pagination");
let queryPage=1;
let queryCategoryDepth=1;
function label(group){return group.main_keyword ?? group.sibling_keywords.join(" ／ ")}
function renderDetail(group){
  const keywords=group.intent_keywords.length?group.intent_keywords:group.sibling_keywords;
  const compared=group.comparison_keywords;
  const judgment=group.comparison_keywords.length>1?`群内最低SERP一致 ${Math.round(group.overlap.ratio*100)}%`:"単独キーワード";
  const gate=group.article_gate;
  const passed=gate.conditions.filter((condition)=>condition.status==="pass").length;
  detail.innerHTML=`<span class="badge ${group.confidence}">${judgment}</span><h2>${label(group)}</h2><p class="detail-label">${group.main_origin}</p>
    <div class="detail-block"><h3>施策判断</h3><div class="detail-row"><span>判定</span><strong>${group.strategy.decision}</strong></div><div class="detail-row"><span>施策記事数</span><strong>${group.strategy.article_count}件</strong></div><div class="detail-row"><span>メインKWの根拠</span><strong>${group.strategy.main_basis}</strong></div><div class="detail-row"><span>メインKW検索Vol</span><strong>${formatVolume(group.search_volume)}</strong></div><div class="detail-row"><span>SERP群</span><strong>${group.comparison_keywords.length>1?`${group.overlap.shared}/${group.overlap.depth} URL一致（群内最低）`:"比較対象なし"}</strong></div><div class="detail-row"><span>AIO出現</span><strong>${group.strategy.aio_observed_queries}/${group.strategy.aio_checked_queries} KW</strong></div><div class="detail-row"><span>クリック余地</span><strong>${group.strategy.click_opportunity}</strong></div><div class="chips">${keywords.map((kw)=>`<span class="chip">${kw}</span>`).join("")}</div></div>
    <div class="detail-block"><h3>記事の成立条件</h3><div class="gate-summary"><strong>${gate.status}</strong><span>${passed}/${gate.conditions.length} 条件成立</span></div><div class="gate-list">${gate.conditions.map((condition)=>`<div class="gate-item"><span class="gate-status ${condition.status}">${condition.status}</span><span><strong>${condition.label}</strong><small>${condition.detail}</small></span></div>`).join("")}</div></div>
    <div class="detail-block"><div class="detail-label">SERP比較証跡</div><div class="detail-row"><span>比較ペア</span><strong>${compared.join(" ↔ ")}</strong></div><div class="detail-row"><span>DFS費用</span><strong>$${group.cost.toFixed(4)}</strong></div>${group.shared_urls.length?`<ul class="url-list">${group.shared_urls.map((url)=>`<li title="${url}">${url}</li>`).join("")}</ul>`:""}</div>
    <div class="detail-block"><div class="detail-label">DFS Task ID</div>${group.task_ids.map((id)=>`<div class="detail-row"><code>${id}</code></div>`).join("")}</div>`;
}
const compareSourceOrder=(left,right)=>left.group.source_order.file-right.group.source_order.file||left.group.source_order.sheet-right.group.source_order.sheet||left.group.source_order.row-right.group.source_order.row;
const allKeywordRows=data.groups.filter((group)=>group.main_keyword).map((group)=>({keyword:group.main_keyword,parent:group.main_keyword,group}));
let keywordRows=[];
const option=(value)=>`<option value="${value}">${value}</option>`;
function resetFilter(select){while(select.options.length>1)select.remove(1);select.value="all"}
function refillCategoryFilter(select,values){const previous=select.value;resetFilter(select);values.filter(Boolean).sort((a,b)=>a.localeCompare(b,"ja")).forEach((value)=>select.insertAdjacentHTML("beforeend",option(value)));select.value=[...select.options].some((item)=>item.value===previous)?previous:"all"}
function syncCategoryFilters(){const parent=filters.categoryParent.value;const childRows=keywordRows.filter((row)=>parent==="all"||row.group.category_path?.[0]===parent);refillCategoryFilter(filters.categoryChild,[...new Set(childRows.map((row)=>row.group.category_path?.[1]))]);const child=filters.categoryChild.value;const grandchildRows=childRows.filter((row)=>child==="all"||row.group.category_path?.[1]===child);refillCategoryFilter(filters.categoryGrandchild,[...new Set(grandchildRows.map((row)=>row.group.category_path?.[2]))])}
function selectSite(){keywordRows=allKeywordRows.filter((row)=>row.group.site_id===siteSelector.value).sort(compareSourceOrder);categoryDepth=Math.max(1,...keywordRows.map((row)=>row.group.category_path?.length??1));document.querySelector("#category-child-head").hidden=categoryDepth<2;document.querySelector("#category-grandchild-head").hidden=categoryDepth<3;filters.categoryChild.hidden=categoryDepth<2;filters.categoryGrandchild.hidden=categoryDepth<3;currentPage=1;Object.values(filters).forEach((filter)=>{if(filter.tagName==="SELECT")resetFilter(filter);else filter.value=""});refillCategoryFilter(filters.categoryParent,[...new Set(keywordRows.map((row)=>row.group.category_path?.[0]))]);syncCategoryFilters();[...new Set(keywordRows.map((row)=>row.parent))].forEach((value)=>filters.parent.insertAdjacentHTML("beforeend",option(value)));[...new Set(keywordRows.map((row)=>row.group.state))].forEach((value)=>filters.state.insertAdjacentHTML("beforeend",option(value)));setupQueryFilters();renderMetrics(keywordRows.map((row)=>row.group));renderRows();renderArticleQueries();renderEmptyViews()}
function renderRows(){
  const query=filters.search.value.trim().toLocaleLowerCase("ja-JP");
  const rows=keywordRows.filter((row)=>(!query||`${row.keyword} ${row.parent??""}`.toLocaleLowerCase("ja-JP").includes(query))&&(filters.categoryParent.value==="all"||row.group.category_path?.[0]===filters.categoryParent.value)&&(filters.categoryChild.value==="all"||row.group.category_path?.[1]===filters.categoryChild.value)&&(filters.categoryGrandchild.value==="all"||row.group.category_path?.[2]===filters.categoryGrandchild.value)&&(filters.parent.value==="all"||row.parent===filters.parent.value)&&(filters.state.value==="all"||row.group.state===filters.state.value));
  const pageSize=pageSizeControl.value==="all"?Math.max(rows.length,1):Number(pageSizeControl.value);
  const pageCount=Math.max(1,Math.ceil(rows.length/pageSize));
  currentPage=Math.min(currentPage,pageCount);
  const start=(currentPage-1)*pageSize;
  const visibleRows=rows.slice(start,start+pageSize);
  rowsRoot.innerHTML=visibleRows.map((row)=>{const aioPresent=row.group.strategy.aio_observed_queries>0;const path=row.group.category_path??[row.group.category];const categories=Array.from({length:categoryDepth},(_,index)=>path[index]??"—");return `<tr data-id="${row.group.id}">${categories.map((category)=>`<td>${category}</td>`).join("")}<td><strong>${row.keyword}</strong></td><td class="search-volume"><strong>${row.group.search_volume==null?"未取得":yen.format(row.group.search_volume)}</strong></td><td>${row.group.intent_keywords.length}語</td><td><span class="aio-state ${aioPresent?"present":"absent"}">${aioPresent?"あり":"なし"}</span></td><td>${row.group.state}</td><td>${row.group.wp_article_id??"—"}</td><td><button class="detail-button" type="button">詳細</button></td></tr>`}).join("");
  rowsRoot.querySelectorAll("tr").forEach((tr)=>{const group=data.groups.find((item)=>item.id===tr.dataset.id);tr.querySelector(".search-volume strong").textContent=formatVolume(group.search_volume)});
  document.querySelector("#table-empty").innerHTML=rows.length?"":"<div class='empty'><strong>該当KWなし</strong><span>フィルターを変更してください。</span></div>";
  pagination.innerHTML=rows.length?`<span><strong>${start+1}–${Math.min(start+pageSize,rows.length)}</strong> / ${rows.length}件</span><button id="page-prev" type="button" ${currentPage===1?"disabled":""}>前へ</button><span>${currentPage} / ${pageCount}ページ</span><button id="page-next" type="button" ${currentPage===pageCount?"disabled":""}>次へ</button>`:"";
  pagination.querySelector("#page-prev")?.addEventListener("click",()=>{currentPage-=1;renderRows()});
  pagination.querySelector("#page-next")?.addEventListener("click",()=>{currentPage+=1;renderRows()});
  if(!rows.length){detail.innerHTML="";return}
  rowsRoot.querySelectorAll(".detail-button").forEach((button)=>button.addEventListener("click",()=>{const row=button.closest("tr");renderDetail(data.groups.find((group)=>group.id===row.dataset.id));dialog.showModal()}));
}
const siteArticleQueries=()=>data.article_queries.filter((row)=>row.site_id===siteSelector.value);
function queryPathMatches(row,parent,child,grandchild){return (row.category_paths.length?row.category_paths:[[]]).some((path)=>(parent==="all"||path[0]===parent)&&(child==="all"||path[1]===child)&&(grandchild==="all"||path[2]===grandchild))}
function refillQueryCategoryFilter(select,values){refillCategoryFilter(select,values)}
function syncQueryCategoryFilters(){const rows=siteArticleQueries();const parent=queryFilters.categoryParent.value;const childPaths=rows.flatMap((row)=>row.category_paths).filter((path)=>parent==="all"||path[0]===parent);refillQueryCategoryFilter(queryFilters.categoryChild,[...new Set(childPaths.map((path)=>path[1]))]);const child=queryFilters.categoryChild.value;const grandchildPaths=childPaths.filter((path)=>child==="all"||path[1]===child);refillQueryCategoryFilter(queryFilters.categoryGrandchild,[...new Set(grandchildPaths.map((path)=>path[2]))])}
function setupQueryFilters(){const rows=siteArticleQueries();queryCategoryDepth=Math.max(1,...rows.flatMap((row)=>row.category_paths.map((path)=>path.length)));document.querySelector("#query-category-child-head").hidden=queryCategoryDepth<2;document.querySelector("#query-category-grandchild-head").hidden=queryCategoryDepth<3;queryFilters.categoryChild.hidden=queryCategoryDepth<2;queryFilters.categoryGrandchild.hidden=queryCategoryDepth<3;queryPage=1;Object.values(queryFilters).forEach((filter)=>{if(filter.tagName==="SELECT")resetFilter(filter);else filter.value=""});refillQueryCategoryFilter(queryFilters.categoryParent,[...new Set(rows.flatMap((row)=>row.category_paths.map((path)=>path[0])))]);syncQueryCategoryFilters();const articles=[...new Map(rows.map((row)=>[row.wp_article_id,row])).values()].sort((left,right)=>left.wp_article_id-right.wp_article_id);articles.forEach((row)=>queryFilters.article.insertAdjacentHTML("beforeend",`<option value="${row.wp_article_id}">${row.wp_article_id} · ${row.title}</option>`));[...new Set(rows.map((row)=>row.window_days))].sort((a,b)=>a-b).forEach((days)=>queryFilters.period.insertAdjacentHTML("beforeend",`<option value="${days}">過去${days}日</option>`))}
function selectedQueryPath(row){const parent=queryFilters.categoryParent.value,child=queryFilters.categoryChild.value,grandchild=queryFilters.categoryGrandchild.value;return row.category_paths.find((path)=>(parent==="all"||path[0]===parent)&&(child==="all"||path[1]===child)&&(grandchild==="all"||path[2]===grandchild))??row.category_paths[0]??[]}
function renderArticleQueries(){const search=queryFilters.search.value.trim().toLocaleLowerCase("ja-JP");const rows=siteArticleQueries().filter((row)=>(!search||`${row.query} ${row.title} ${row.wp_article_id}`.toLocaleLowerCase("ja-JP").includes(search))&&queryPathMatches(row,queryFilters.categoryParent.value,queryFilters.categoryChild.value,queryFilters.categoryGrandchild.value)&&(queryFilters.article.value==="all"||String(row.wp_article_id)===queryFilters.article.value)&&(queryFilters.period.value==="all"||String(row.window_days)===queryFilters.period.value));const pageSize=queryPageSizeControl.value==="all"?Math.max(rows.length,1):Number(queryPageSizeControl.value);const pageCount=Math.max(1,Math.ceil(rows.length/pageSize));queryPage=Math.min(queryPage,pageCount);const start=(queryPage-1)*pageSize;const visibleRows=rows.slice(start,start+pageSize);queryRowsRoot.innerHTML=visibleRows.map((row)=>{const path=selectedQueryPath(row);const categories=Array.from({length:queryCategoryDepth},(_,index)=>path[index]??"—");return `<tr>${categories.map((category)=>`<td>${category}</td>`).join("")}<td><strong>${row.title}</strong><span class="cell-note" title="${row.url}">${row.url}</span></td><td>${row.wp_article_id}</td><td><strong>${row.query}</strong></td><td>${yen.format(row.impressions)}</td><td>${yen.format(row.clicks)}</td><td>${Number(row.position).toFixed(2)}</td><td>過去${row.window_days}日<span class="cell-note">${new Date(row.observed_at).toLocaleString("ja-JP")}取得</span></td></tr>`}).join("");const empty=document.querySelector("#query-empty");empty.hidden=rows.length>0;empty.innerHTML=rows.length?"":`<strong>記事別クエリは未取得です</strong><span>GSCをpage × queryで取得すると表示されます。ページ別・クエリ別の独立集計は推測結合しません。</span>`;queryPagination.innerHTML=rows.length?`<span><strong>${start+1}–${Math.min(start+pageSize,rows.length)}</strong> / ${rows.length}件</span><button id="query-page-prev" type="button" ${queryPage===1?"disabled":""}>前へ</button><span>${queryPage} / ${pageCount}ページ</span><button id="query-page-next" type="button" ${queryPage===pageCount?"disabled":""}>次へ</button>`:"";queryPagination.querySelector("#query-page-prev")?.addEventListener("click",()=>{queryPage-=1;renderArticleQueries()});queryPagination.querySelector("#query-page-next")?.addEventListener("click",()=>{queryPage+=1;renderArticleQueries()})}
[filters.search,filters.parent,filters.state].forEach((filter)=>filter.addEventListener(filter.type==="search"?"input":"change",()=>{currentPage=1;renderRows()}));filters.categoryParent.addEventListener("change",()=>{filters.categoryChild.value="all";filters.categoryGrandchild.value="all";syncCategoryFilters();currentPage=1;renderRows()});filters.categoryChild.addEventListener("change",()=>{filters.categoryGrandchild.value="all";syncCategoryFilters();currentPage=1;renderRows()});filters.categoryGrandchild.addEventListener("change",()=>{currentPage=1;renderRows()});pageSizeControl.addEventListener("change",()=>{currentPage=1;renderRows()});siteSelector.querySelectorAll(".site-tab").forEach((tab)=>tab.addEventListener("click",()=>activateSite(tab.dataset.site)));
[queryFilters.search,queryFilters.article,queryFilters.period].forEach((filter)=>filter.addEventListener(filter.type==="search"?"input":"change",()=>{queryPage=1;renderArticleQueries()}));queryFilters.categoryParent.addEventListener("change",()=>{queryFilters.categoryChild.value="all";queryFilters.categoryGrandchild.value="all";syncQueryCategoryFilters();queryPage=1;renderArticleQueries()});queryFilters.categoryChild.addEventListener("change",()=>{queryFilters.categoryGrandchild.value="all";syncQueryCategoryFilters();queryPage=1;renderArticleQueries()});queryFilters.categoryGrandchild.addEventListener("change",()=>{queryPage=1;renderArticleQueries()});queryPageSizeControl.addEventListener("change",()=>{queryPage=1;renderArticleQueries()});

function renderEmptyViews(){const site=data.sites.find((item)=>item.site_id===siteSelector.value);document.querySelector("#link-map").innerHTML=`<div class="map-placeholder"><strong>${site.label}の内部リンク構造は未生成です</strong><span>このサイトのWP記事IDを取得し、記事本文から内部リンクを抽出した後に表示します。他サイトの記事やリンクは混在させません。</span></div>`}
